-- MIARADI-TRAVEL — ajout du circuit signature Nord – Nord-Ouest au catalogue administrable.
-- Exécuter sur la base MIARADI locale après sauvegarde.
-- Idempotent : conserve les champs d'un circuit/page déjà existants.
-- Source du contenu : circuit-nord-nord-ouest.html.
-- Note de contenu : la page source annonce 19 jours mais contient 17 blocs d'étape
-- (les intitulés passent du jour 08 au jour 11). Ce script conserve le contenu source
-- sans inventer les deux journées manquantes ; elles pourront être ajoutées dans l'admin.

SET NAMES utf8mb4;

INSERT INTO miaradi_circuits
  (slug, title_fr, title_en, summary_fr, summary_en, region, theme,
   duration_min, duration_max, image_path, is_published, sort_order)
VALUES
  ('nord-nord-ouest', 'Nord – Nord-Ouest de Madagascar', 'North – North-West Madagascar',
   'Un circuit de 19 jours entre les Hautes Terres, le Boeny, le fleuve Sofia, les paysages du Nord et les îles de Nosy Be.', 'A 19-day journey across the Highlands, Boeny, the Sofia River, northern landscapes and the islands of Nosy Be.',
   'Nord – Nord-Ouest', 'nature', 19, 19, 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?auto=format&fit=crop&w=2200&q=85', 1, 20)
ON DUPLICATE KEY UPDATE id = LAST_INSERT_ID(id);

UPDATE miaradi_circuits SET is_published = 1 WHERE slug = 'nord-nord-ouest';

INSERT INTO miaradi_circuit_pages
  (circuit_id, hero_title_fr, hero_title_en, intro_fr, intro_en, hero_image, itinerary_json, is_published)
SELECT c.id,
       'Au fil des paysages et du fleuve Sofia',
       'Along the landscapes and the Sofia River',
       'Un circuit de 19 jours entre les Hautes Terres, le Boeny, le fleuve Sofia, les paysages du Nord et les îles de Nosy Be.',
       'A 19-day journey between contrasting territories, remarkable natural heritage and encounters with local communities.',
       'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?auto=format&fit=crop&w=2200&q=85',
       '[{"title":"Arrivée à Antananarivo","subtitle":"Installation & premiers repères","description":"Accueil à l’aéroport d’Ivato par l’équipe MIARADI, transfert et installation à l’hôtel. Selon l’heure d’arrivée, première promenade aux alentours et présentation du voyage.","overnight":"hôtel à Antananarivo.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Antananarivo%20city.jpg?width=1200","alt":"Arrivée à Antananarivo — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/L%27entr%C3%A9e%20du%20Rova%20Antsahadinta%2001.jpg?width=1200","alt":"Arrivée à Antananarivo — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/L%27entr%C3%A9e%20du%20Rova%20Antsahadinta%2002.jpg?width=1200","alt":"Arrivée à Antananarivo — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Antananarivo%20city.jpg?width=1200","alt":"Arrivée à Antananarivo — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/L%27entr%C3%A9e%20du%20village%20du%20Rova%20Antsahadinta%2001.jpg?width=1200","alt":"Arrivée à Antananarivo — photo 5 sur 5"}]},{"title":"Antananarivo – Maevatanana – Ambondromamy","subtitle":"La route vers le Nord-Ouest","description":"Grande traversée par la route. Les reliefs et rizières des Hautes Terres laissent place aux vallées, plaines et savanes de l’Ouest, avec des haltes dans les villages traversés.","overnight":"hôtel à Ambondromamy.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Antananarivo%20city.jpg?width=1200","alt":"Antananarivo – Maevatanana – Ambondromamy — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Walking_the_Avenue_of_the_Baobabs.jpg?width=1200","alt":"Antananarivo – Maevatanana – Ambondromamy — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2001.jpg?width=1200","alt":"Antananarivo – Maevatanana – Ambondromamy — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2002.jpg?width=1200","alt":"Antananarivo – Maevatanana – Ambondromamy — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2003.jpg?width=1200","alt":"Antananarivo – Maevatanana – Ambondromamy — photo 5 sur 5"}]},{"title":"Ambondromamy – Ankarafantsika","subtitle":"Forêt sèche & canyons","description":"Découverte du secteur d’Ankarokaroka et de ses formations sculptées par l’érosion. Une sortie nocturne accompagnée pourra permettre d’observer la faune active à la tombée du jour.","overnight":"hébergement dans le secteur du parc.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2001.jpg?width=1200","alt":"Ambondromamy – Ankarafantsika — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2002.jpg?width=1200","alt":"Ambondromamy – Ankarafantsika — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2003.jpg?width=1200","alt":"Ambondromamy – Ankarafantsika — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2004.jpg?width=1200","alt":"Ambondromamy – Ankarafantsika — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2005.jpg?width=1200","alt":"Ambondromamy – Ankarafantsika — photo 5 sur 5"}]},{"title":"Ankarafantsika – Majunga","subtitle":"De la forêt à la côte du Boeny","description":"Route vers Majunga, tour de ville, découverte des quartiers emblématiques et du célèbre baobab du front de mer, puis promenade au coucher du soleil.","overnight":"hôtel à Majunga.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20baobab%2C%20Mahajanga.jpg?width=1200","alt":"Ankarafantsika – Majunga — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Baobab%20arbre%20de%20Mahajanga%20Madagascar.jpg?width=1200","alt":"Ankarafantsika – Majunga — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Baobab%20de%20mahajanga.jpg?width=1200","alt":"Ankarafantsika – Majunga — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Baobab%20du%20bord%20de%20la%20mer%20mahajanga.jpg?width=1200","alt":"Ankarafantsika – Majunga — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Mahajanga%20baobab%2001.jpg?width=1200","alt":"Ankarafantsika – Majunga — photo 5 sur 5"}]},{"title":"Majunga – Boeny Aranta – Antsoheribory","subtitle":"Patrimoine maritime","description":"Navigation vers l’îlot d’Antsoheribory pour découvrir les vestiges historiques, puis continuation en pirogue vers un village de pêcheurs et rencontre avec les traditions maritimes locales.","overnight":"bivouac ou hébergement local, à confirmer.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Antsoheribory.jpg?width=1200","alt":"Majunga – Boeny Aranta – Antsoheribory — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20de%20Mahajanga.jpg?width=1200","alt":"Majunga – Boeny Aranta – Antsoheribory — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Village%20%C3%A0%20Mahajanga.jpg?width=1200","alt":"Majunga – Boeny Aranta – Antsoheribory — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Quai%20Orange%2005.jpg?width=1200","alt":"Majunga – Boeny Aranta – Antsoheribory — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Debarquadaire%20de%20Katsepy.jpg?width=1200","alt":"Majunga – Boeny Aranta – Antsoheribory — photo 5 sur 5"}]},{"title":"Boeny Aranta – Katsepy – Majunga","subtitle":"Phare historique & baie de Bombetoka","description":"Départ en 4x4 vers Katsepy, découverte du phare et des panoramas sur la baie, les mangroves et l’embouchure de la Betsiboka. Retour en bateau à Majunga.","overnight":"hôtel à Majunga.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Phare%20Eiffel%2C%20Katsepy%2C%20R%C3%A9gion%20Boeny.jpg?width=1200","alt":"Boeny Aranta – Katsepy – Majunga — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Phare%20Eiffel%2C%20Katsepy%2C%20R%C3%A9gion%20Boeny%20(10935).jpg?width=1200","alt":"Boeny Aranta – Katsepy – Majunga — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Phare%20Eiffel%2C%20Katsepy%2C%20R%C3%A9gion%20Boeny%20(13160).jpg?width=1200","alt":"Boeny Aranta – Katsepy – Majunga — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Debarquadaire%20de%20Katsepy.jpg?width=1200","alt":"Boeny Aranta – Katsepy – Majunga — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Lighthouse%20%26%20Branches%20%E2%80%94%20Katsepy(Mahajanga).jpg?width=1200","alt":"Boeny Aranta – Katsepy – Majunga — photo 5 sur 5"}]},{"title":"Majunga – Antanamarina","subtitle":"À travers les savanes du Boeny","description":"Route en 4x4 à travers les savanes et villages ruraux, halte au jacuzzi naturel et continuation vers Antanamarina, point de départ de l’exploration d’Anjohibe.","overnight":"hôtel de brousse à Antanamarina.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2001.jpg?width=1200","alt":"Majunga – Antanamarina — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2002.jpg?width=1200","alt":"Majunga – Antanamarina — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20sein%20du%20Parc%20National%20d%27Ankarafantsika%2003.jpg?width=1200","alt":"Majunga – Antanamarina — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20arbre%20d%27Ankarafantsika.jpg?width=1200","alt":"Majunga – Antanamarina — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Walking_the_Avenue_of_the_Baobabs.jpg?width=1200","alt":"Majunga – Antanamarina — photo 5 sur 5"}]},{"title":"Les grottes d’Anjohibe","subtitle":"Patrimoine souterrain & panoramas","description":"Exploration guidée des galeries et formations calcaires, temps de détente près de la cascade, puis panorama depuis Zahariaka sur la baie de Mahajamba et ses mangroves.","overnight":"hôtel de brousse à Antanamarina.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Grotte%20d%27Anjohibe%2001.jpg?width=1200","alt":"Les grottes d’Anjohibe — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Grotte%20d%27Anjohibe%2004.jpg?width=1200","alt":"Les grottes d’Anjohibe — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Grotte%20d%27Anjohibe%2005.jpg?width=1200","alt":"Les grottes d’Anjohibe — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Fossiles%20d%27Anjohibe.jpg?width=1200","alt":"Les grottes d’Anjohibe — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Fossiles%20dans%20grotte%20Anjohibe.jpg?width=1200","alt":"Les grottes d’Anjohibe — photo 5 sur 5"}]},{"title":"Antsohihy – Ambanja – Ambilobe","subtitle":"Au pays du cacao du Sambirano","description":"Route vers Ambanja et visite d’une plantation de cacao pour découvrir la culture, la récolte, la fermentation et le séchage des fèves. Rencontre avec les producteurs, puis continuation vers Ambilobe.","overnight":"hôtel à Ambilobe.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Champ%20de%20cacao%20Ambanja.jpg?width=1200","alt":"Antsohihy – Ambanja – Ambilobe — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/AMBANJA.jpg?width=1200","alt":"Antsohihy – Ambanja – Ambilobe — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Ambanja%20(Madagascar).jpg?width=1200","alt":"Antsohihy – Ambanja – Ambilobe — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Koperative%20tsaravintana.jpg?width=1200","alt":"Antsohihy – Ambanja – Ambilobe — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Bazar%20Be%20Ambanja.jpg?width=1200","alt":"Antsohihy – Ambanja – Ambilobe — photo 5 sur 5"}]},{"title":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges","subtitle":"Paysages minéraux du Nord","description":"Exploration guidée des formations calcaires de l’Ankarana, puis route vers Sadjoavato et les Tsingy Rouges. Des haltes pourront faire découvrir l’artisanat et les traditions culinaires locales.","overnight":"hébergement à proximité des Tsingy Rouges.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2001.jpg?width=1200","alt":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2002.jpg?width=1200","alt":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2003.jpg?width=1200","alt":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2004.jpg?width=1200","alt":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20Rouges%20Madagascar%20-%20panoramio.jpg?width=1200","alt":"Ambilobe – Ankarana – Sadjoavato – Tsingy Rouges — photo 5 sur 5"}]},{"title":"Tsingy Rouges – Diego-Suarez – Montagne des Français","subtitle":"Couleurs du Nord & coucher de soleil","description":"Visite des Tsingy Rouges, continuation vers Diego-Suarez puis panorama en fin de journée depuis la Montagne des Français, selon le timing et les conditions.","overnight":"hôtel à Diego-Suarez.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2002.jpg?width=1200","alt":"Tsingy Rouges – Diego-Suarez – Montagne des Français — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2005.jpg?width=1200","alt":"Tsingy Rouges – Diego-Suarez – Montagne des Français — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20rouge%20de%20Diego%2009.jpg?width=1200","alt":"Tsingy Rouges – Diego-Suarez – Montagne des Français — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsingy%20Rouge%2C%20Nth%20Madagascar.jpg?width=1200","alt":"Tsingy Rouges – Diego-Suarez – Montagne des Français — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2010.jpg?width=1200","alt":"Tsingy Rouges – Diego-Suarez – Montagne des Français — photo 5 sur 5"}]},{"title":"Les trois baies de Diego-Suarez","subtitle":"Plages sauvages & eaux turquoise","description":"Découverte de la baie des Sakalava, de la baie des Pigeons et de la baie des Dunes. Baignade possible selon l’état de la mer et les conditions de sécurité.","overnight":"hôtel à Diego-Suarez.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2010.jpg?width=1200","alt":"Les trois baies de Diego-Suarez — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2011.jpg?width=1200","alt":"Les trois baies de Diego-Suarez — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2012.jpg?width=1200","alt":"Les trois baies de Diego-Suarez — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2013.jpg?width=1200","alt":"Les trois baies de Diego-Suarez — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Les%203%20baies%20d%27Antsiranana%2014.jpg?width=1200","alt":"Les trois baies de Diego-Suarez — photo 5 sur 5"}]},{"title":"Diego-Suarez – Ambanja – Ankify – Nosy Be","subtitle":"Du continent à l’île aux parfums","description":"Route vers Ankify à travers les paysages du Nord et le Sambirano, puis traversée maritime vers Nosy Be. Visite du mont Passot possible si les horaires le permettent.","overnight":"hôtel à Nosy Be.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Andilana%20beach%20Nosy%20Be%202013-10-24%2020-29.jpg?width=1200","alt":"Diego-Suarez – Ambanja – Ankify – Nosy Be — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Madagascar%20Nosyb%C3%A9.jpg?width=1200","alt":"Diego-Suarez – Ambanja – Ankify – Nosy Be — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20lone%20fisherman%20in%20Nosey%20Be.jpg?width=1200","alt":"Diego-Suarez – Ambanja – Ankify – Nosy Be — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Fishermen%20in%20Nosey%20Be.jpg?width=1200","alt":"Diego-Suarez – Ambanja – Ankify – Nosy Be — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Gare%20maritime%20de%20Nosy%20Be.jpg?width=1200","alt":"Diego-Suarez – Ambanja – Ankify – Nosy Be — photo 5 sur 5"}]},{"title":"Excursion à Nosy Sakatia","subtitle":"Une île authentique","description":"Excursion en bateau pour découvrir les plages, la végétation tropicale et les villages. Baignade ou snorkeling possibles selon la météo et la visibilité, avec observation respectueuse de la faune lorsqu’elle se présente.","overnight":"hôtel à Nosy Be.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20and%20small%20village%20on%20the%20island%20Nosy%20Sakatia%20(1).jpg?width=1200","alt":"Excursion à Nosy Sakatia — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Ile%20Sakatia%20de%20Nosy%20b%C3%A9%2002.jpg?width=1200","alt":"Excursion à Nosy Sakatia — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Sakatia%20photographed%20from%20the%20sea%20(1).jpg?width=1200","alt":"Excursion à Nosy Sakatia — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20and%20small%20village%20on%20the%20island%20Nosy%20Sakatia%20(2).jpg?width=1200","alt":"Excursion à Nosy Sakatia — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Sakatia%20Island%20at%20sunset%2C%20photo%20from%20Nosy%20Be%20Island%20(1).jpg?width=1200","alt":"Excursion à Nosy Sakatia — photo 5 sur 5"}]},{"title":"Découverte culturelle de Marodoka","subtitle":"Histoire & parfums de Nosy Be","description":"Découverte de l’histoire de Marodoka et des influences culturelles de l’archipel. Une visite complémentaire de Lémuria Land peut être envisagée, à confirmer lors de la préparation du circuit.","overnight":"hôtel à Nosy Be.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20community%20in%20Nosey%20Be.jpg?width=1200","alt":"Découverte culturelle de Marodoka — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Au%20march%C3%A9%20de%20Nosy%20Be.jpg?width=1200","alt":"Découverte culturelle de Marodoka — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Fishermen%20in%20Nosey%20Be.jpg?width=1200","alt":"Découverte culturelle de Marodoka — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20lone%20fisherman%20in%20Nosey%20Be.jpg?width=1200","alt":"Découverte culturelle de Marodoka — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20community%20in%20Nosey%20Be.jpg?width=1200","alt":"Découverte culturelle de Marodoka — photo 5 sur 5"}]},{"title":"Excursion à Nosy Iranja","subtitle":"Deux îlots & banc de sable blanc","description":"Navigation vers Nosy Iranja, découverte du banc de sable dépendant des marées, promenade, temps de plage et déjeuner selon l’organisation locale et les conditions maritimes.","overnight":"hôtel à Nosy Be.","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Iranja%20beaches%2001.jpg?width=1200","alt":"Excursion à Nosy Iranja — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Iranja%20-%20vue%20de%20haut.jpg?width=1200","alt":"Excursion à Nosy Iranja — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Bateau%20vers%20Nosy%20Iranja.jpg?width=1200","alt":"Excursion à Nosy Iranja — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Iranja%20beaches%2002.jpg?width=1200","alt":"Excursion à Nosy Iranja — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Nosy%20Iranja%20village%2001.jpg?width=1200","alt":"Excursion à Nosy Iranja — photo 5 sur 5"}]},{"title":"Nosy Be – Départ","subtitle":"Fin du voyage","description":"Temps libre selon l’horaire du vol, puis transfert à l’aéroport international de Nosy Be et assistance de l’équipe MIARADI.","overnight":"","images":[{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Andilana%20beach%20Nosy%20Be%202013-10-24%2020-29.jpg?width=1200","alt":"Nosy Be – Départ — photo 1 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Madagascar%20Nosyb%C3%A9.jpg?width=1200","alt":"Nosy Be – Départ — photo 2 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/A%C3%A9roport%20de%20fascene%20Nosy%20Be%2001.jpg?width=1200","alt":"Nosy Be – Départ — photo 3 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Gare%20maritime%20de%20Nosy%20Be.jpg?width=1200","alt":"Nosy Be – Départ — photo 4 sur 5"},{"url":"https://commons.wikimedia.org/wiki/Special:FilePath/Mont%20passot.jpg?width=1200","alt":"Nosy Be – Départ — photo 5 sur 5"}]}]',
       1
FROM miaradi_circuits c
WHERE c.slug = 'nord-nord-ouest'
  AND NOT EXISTS (
    SELECT 1 FROM miaradi_circuit_pages p WHERE p.circuit_id = c.id
  );
